begin;
create or replace function public.save_consolidation_fx_rate(target_group_id uuid,target_currency text,target_rate_date date,target_rate_type text,target_rate_to_reporting numeric)returns uuid language plpgsql security invoker set search_path='' as $$declare actor uuid:=(select auth.uid());lead_id uuid;new_id uuid;normalized_currency text:=upper(btrim(target_currency));begin if actor is null or not private.is_platform_administrator()then raise exception 'platform administrator access required' using errcode='42501';end if;select lead_academy_id into lead_id from public.consolidation_groups where id=target_group_id and active;if lead_id is null or normalized_currency!~'^[A-Z]{3}$' or target_rate_type not in('average','closing')or target_rate_to_reporting<=0 or target_rate_to_reporting>=1000000 then raise exception 'invalid consolidation FX rate' using errcode='22023';end if;insert into public.consolidation_fx_rates(group_id,currency,rate_date,rate_type,rate_to_reporting,created_by)values(target_group_id,normalized_currency,target_rate_date,target_rate_type,target_rate_to_reporting,actor)on conflict(group_id,currency,rate_date,rate_type)do update set rate_to_reporting=excluded.rate_to_reporting,updated_at=now()returning id into new_id;perform public.write_audit_event(lead_id,'consolidation.fx_rate_saved','consolidation_fx_rate',new_id,jsonb_build_object('currency',normalized_currency,'rate_type',target_rate_type,'rate_date',target_rate_date));return new_id;end;$$;
revoke all on function public.save_consolidation_fx_rate(uuid,text,date,text,numeric) from public,anon,authenticated;
grant execute on function public.save_consolidation_fx_rate(uuid,text,date,text,numeric) to authenticated;
commit;
